// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Private_Bank, Log} from "../src/Private_Bank.sol";

contract InvMutTest is Test {
    Private_Bank c;
    function setUp() public { c = new Private_Bank(address(new Log())); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 2 ether, 100 ether);
        address actor = address(new AlwaysRevert());
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: amount}(abi.encodeWithSignature("Deposit()"));
        require(ok, "deposit failed");
        uint256 beforeBal = c.balances(actor);
        vm.prank(actor);
        (bool success,) = address(c).call(abi.encodeWithSignature("CashOut(uint256)", amount));
        uint256 afterBal = c.balances(actor);
        assertTrue(!(afterBal < beforeBal && success));
    }
}

contract AlwaysRevert {
    receive() external payable { revert(); }
    fallback() external payable { revert(); }
}
